    private val cache = HashMap<String, ImageVector>()

    private fun make(name: String, d: String): ImageVector = cache.getOrPut(name) {
        // Material Symbols' viewBox is "0 -960 960 960": the path is moved down by 960 into the viewport
        val nodes = PathParser().parsePathString(d).toNodes()
        ImageVector.Builder(name, 24.dp, 24.dp, 960f, 960f)
            .addGroup(translationY = 960f)
            .addPath(nodes, fill = SolidColor(Color.Black))
            .clearGroup()
            .build()
    }

    fun of(t: SettingsTopic): ImageVector = when (t) {
        SettingsTopic.TRIPS -> make("bus", P.TRIPS)
        SettingsTopic.PLACES -> make("home", P.PLACES)
        SettingsTopic.SCHOOL -> make("school", P.SCHOOL)
        SettingsTopic.FRIENDS -> make("group", P.FRIENDS)
        SettingsTopic.MAP -> make("map", P.MAP)
        SettingsTopic.NOTIFICATIONS -> make("bell", P.NOTIFICATIONS)
        SettingsTopic.BATTERY -> make("battery", P.BATTERY)
        SettingsTopic.SHARE -> make("heart", P.SHARE)
        SettingsTopic.ADVANCED -> make("build", P.ADVANCED)
    }
